请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-113

=== 用户原始指令 (query.txt) ===
想要个简洁素净点的横向清理面板，带整体氛围背景。用静态示例数据就行，里面横着排列几个不同的清理选项比如清微信清相册，我可以在上面进行对象勾选绑定。帮我加个一键开启勿扰的系统开关按钮，当待清理垃圾达到百分之八十时提示我注意风险，配色带点橙红紧迫渐变，只要文字色块不要图片。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "想要个简洁素净点的横向清理面板，带整体氛围背景。用静态示例数据就行，里面横着排列几个不同的清理选项比如清微信清相册，我可以在上面进行对象勾选绑定。帮我加个一键开启勿扰的系统开关按钮，当待清理垃圾达到百分之八十时提示我注意风险，配色带点橙红紧迫渐变，只要文字色块不要图片。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "SetSettingSwitch",
        "params": {
          "appBundleName": "com.huawei.hmos.settings",
          "itemName": "do_not_disturb",
          "switchFlag": 1
        }
      }
    }
  ],
  "dataModel": {
    "value": {
      "memory": {
        "title": "一键清理",
        "usageText": "待清理 82%",
        "usageValue": 82,
        "totalValue": 100,
        "riskText": "垃圾超过80%，注意风险",
        "actionText": "开启勿扰",
        "options": {
          "wechat": {
            "label": "清微信",
            "selected": true
          },
          "album": {
            "label": "清相册",
            "selected": false
          }
        }
      }
    }
  },
  "assetCandidates": []
}

